<?php
declare(strict_types=1);
require_once __DIR__.'/lib/services/Session.php'; Session::start();
require_once __DIR__.'/lib/config/Database.php'; require_once __DIR__.'/lib/config/AdminConfig.php'; require_once __DIR__.'/lib/models/Professor.php';
$db=(new Database())->connect(); $model=new Professor($db); $csrf=Session::csrfToken(); $erro=''; $sucesso='';
if ($_SERVER['REQUEST_METHOD']==='POST') {
    $acao=$_POST['acao']??'';
    if (!Session::validarCsrf($_POST['csrf_token']??'')) $erro='Token de segurança inválido.';
    elseif ($acao==='entrar_admin') {
        if (hash_equals(AdminConfig::getSecretCode(), $_POST['codigo_secreto']??'')) { Session::regenerar(); $_SESSION['admin_autenticado']=true; header('Location: admin.php'); exit; } else $erro='Código administrativo inválido.';
    } elseif (empty($_SESSION['admin_autenticado'])) { header('Location: admin.php'); exit; }
    elseif (in_array($acao,['cadastrar_professor','editar_professor'],true)) {
        $id=filter_var($_POST['id']??'',FILTER_VALIDATE_INT) ?: null; $nome=trim($_POST['nome']??''); $ra=trim($_POST['ra']??''); $email=trim($_POST['email']??''); $tipo=$_POST['tipo']??'avaliador'; $senha=$_POST['senha']??'';
        if ($nome===''||$ra===''||$email===''||($acao==='cadastrar_professor'&&$senha==='')) $erro='Preencha todos os campos obrigatórios.';
        elseif (!filter_var($email,FILTER_VALIDATE_EMAIL)) $erro='Digite um e-mail válido.';
        elseif (mb_strlen($nome)>150||mb_strlen($ra)>50||mb_strlen($email)>150) $erro='Um dos campos ultrapassou o limite permitido.';
        elseif ($acao==='cadastrar_professor'&&strlen($senha)<8) $erro='A senha precisa ter pelo menos 8 caracteres.';
        elseif (!in_array($tipo,['orientador','avaliador','coordenador'],true)) $erro='Tipo de professor inválido.';
        elseif ($model->emailExiste($email,$id)||$model->raExiste($ra,$id)) $erro='E-mail ou RA já cadastrado.';
        else { try { if($acao==='cadastrar_professor') $model->criar($nome,$ra,$email,$senha,$tipo); else $model->atualizar((int)$id,$nome,$ra,$email,$tipo,$senha); $sucesso=$acao==='cadastrar_professor'?'Professor cadastrado com sucesso.':'Professor atualizado com sucesso.'; } catch(Throwable $e) { $erro='Não foi possível salvar o professor.'; } }
    } elseif ($acao==='excluir_professor') { $id=filter_var($_POST['id']??'',FILTER_VALIDATE_INT); if(!$id) $erro='Professor inválido.'; else { try{$model->excluir((int)$id);$sucesso='Professor removido com sucesso.';}catch(Throwable $e){$erro='Não foi possível remover o professor.';} } }
}
$autenticado=!empty($_SESSION['admin_autenticado']); $professores=$autenticado?$model->buscarTodos():[];
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Painel Administrativo</title><link rel="stylesheet" href="style.css"><style>.edit-form{display:none}.professor-item.editing .edit-form{display:block}.professor-item.editing .view-data{display:none}.actions{display:flex;gap:8px;flex-wrap:wrap}.button-small{padding:8px 12px;border:0;border-radius:8px;cursor:pointer}.button-edit{background:#e5eefc;color:#16427c}.inline{display:inline}</style></head><body>
<?php if(!$autenticado): ?><main class="auth-page"><section class="auth-card"><div class="auth-icon">🔐</div><h1>Área administrativa</h1><p>Acesse o painel integrado de professores e atendimento.</p><?php if($erro):?><div class="alert alert-error"><?=htmlspecialchars($erro)?></div><?php endif;?><form method="post"><input type="hidden" name="acao" value="entrar_admin"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($csrf)?>"><div class="form-group"><label>Código secreto</label><input type="password" name="codigo_secreto" autocomplete="off" required></div><button class="button button-primary button-full">Acessar painel</button></form><div class="auth-footer"><a href="professor/login.php">Login do professor</a></div></section></main>
<?php else: ?><nav class="navbar"><a href="admin.php" class="navbar-brand">🎓 Sistema Escolar</a><div class="navbar-links"><a class="nav-button active" href="admin.php">👨‍🏫 Professores</a><a class="nav-button" href="admin-chat.php">💬 Chat</a><a class="nav-button nav-danger" href="logout.php">🚪 Sair</a></div></nav><main class="page-container"><header class="page-header"><div><span class="eyebrow">PAINEL ADMINISTRATIVO</span><h1>Professores</h1><p>Cadastro e atendimento em um único painel.</p></div><div class="admin-status">🔐 ADM conectado</div></header><?php if($erro):?><div class="alert alert-error"><?=htmlspecialchars($erro)?></div><?php endif;?><?php if($sucesso):?><div class="alert alert-success"><?=htmlspecialchars($sucesso)?></div><?php endif;?><section class="content-grid"><div class="content-card"><div class="card-header"><h2>Cadastrar professor</h2><p>Crie uma conta para acesso ao sistema.</p></div><form method="post"><input type="hidden" name="acao" value="cadastrar_professor"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($csrf)?>"><div class="form-group"><label>Nome completo</label><input name="nome" maxlength="150" required></div><div class="form-group"><label>RA / matrícula</label><input name="ra" maxlength="50" required></div><div class="form-group"><label>E-mail</label><input type="email" name="email" maxlength="150" required></div><div class="form-group"><label>Tipo</label><select name="tipo"><option value="avaliador">Avaliador</option><option value="orientador">Orientador</option><option value="coordenador">Coordenador</option></select></div><div class="form-group"><label>Senha</label><input type="password" name="senha" minlength="8" required></div><button class="button button-primary button-full">Cadastrar professor</button></form></div><div class="content-card"><div class="card-header"><h2>Professores cadastrados</h2><p><?=count($professores)?> professor(es).</p></div><?php if(!$professores):?><div class="empty-state"><p>Nenhum professor cadastrado ainda.</p></div><?php else:?><div class="professors-list"><?php foreach($professores as $p):?><article class="professor-item" id="prof-<?=$p['id']?>"><div class="view-data"><div class="professor-info"><div class="avatar"><?=htmlspecialchars(strtoupper(substr($p['nome'],0,1)))?></div><div><h3><?=htmlspecialchars($p['nome'])?></h3><p>RA: <?=htmlspecialchars($p['ra'])?></p><p><?=htmlspecialchars($p['email'])?></p><p>Tipo: <?=htmlspecialchars(ucfirst($p['tipo']))?></p></div></div><div class="actions"><button type="button" class="button-small button-edit" onclick="editar(<?=$p['id']?>)">Editar</button><form method="post" class="inline" onsubmit="return confirm('Excluir este professor?')"><input type="hidden" name="acao" value="excluir_professor"><input type="hidden" name="id" value="<?=$p['id']?>"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($csrf)?>"><button class="button-small button-danger">Excluir</button></form></div></div><form class="edit-form" method="post"><input type="hidden" name="acao" value="editar_professor"><input type="hidden" name="id" value="<?=$p['id']?>"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars($csrf)?>"><div class="form-group"><label>Nome</label><input name="nome" value="<?=htmlspecialchars($p['nome'])?>" required></div><div class="form-group"><label>RA</label><input name="ra" value="<?=htmlspecialchars($p['ra'])?>" required></div><div class="form-group"><label>E-mail</label><input type="email" name="email" value="<?=htmlspecialchars($p['email'])?>" required></div><div class="form-group"><label>Tipo</label><select name="tipo"><?php foreach(['avaliador','orientador','coordenador'] as $t):?><option value="<?=$t?>" <?=$p['tipo']===$t?'selected':''?>><?=ucfirst($t)?></option><?php endforeach;?></select></div><div class="form-group"><label>Nova senha (opcional)</label><input type="password" name="senha" minlength="8"></div><div class="actions"><button class="button button-primary">Salvar</button><button type="button" class="button-small" onclick="cancelar(<?=$p['id']?>)">Cancelar</button></div></form></article><?php endforeach;?></div><?php endif;?></div></section></main><script>function editar(id){document.getElementById('prof-'+id).classList.add('editing')}function cancelar(id){document.getElementById('prof-'+id).classList.remove('editing')}</script><?php endif;?></body></html>
